changeSet.sql:
UPDATE n_stage_config
SET stage_config = jsonb_set(
    stage_config,
    '{possibleNextStages}',
    (
        SELECT COALESCE(
            jsonb_agg(
                jsonb_build_object('stageKey', elem, 'allowedRoles', '[]'::jsonb)
            ),
            '[]'::jsonb
        )
        FROM jsonb_array_elements_text(stage_config -> 'possibleNextStages') AS elem
    )
)
WHERE stage_config -> 'possibleNextStages' IS NOT NULL
  AND jsonb_typeof(stage_config -> 'possibleNextStages') = 'array'
  AND (
      jsonb_array_length(stage_config -> 'possibleNextStages') = 0
      OR jsonb_typeof((stage_config -> 'possibleNextStages') -> 0) = 'string'
  );
